export enum ProblemAttemptStatus {
  None = 0,
  Attempt = 1,
  Accept = 2,
}

export enum ProblemRankType {
  Time = 0,
  Memory = 1,
  CodeLength = 2,
}

export function GetProblemRankTypeStr(type: ProblemRankType) {
  switch (type) {
    case ProblemRankType.Time:
      return "优先用时";
    case ProblemRankType.Memory:
      return "优先内存";
    case ProblemRankType.CodeLength:
      return "优先代码长度";
    default:
      return "";
  }
}

export function GetProblemRankTypes() {
  return Object.values(ProblemRankType)
    .filter((v) => typeof v === "number")
    .map((value) => ({
      value,
      label: GetProblemRankTypeStr(value as ProblemRankType),
    })) as { label: string; value: ProblemRankType }[];
}

export function ParseProblem(item: Problem, tagsMap: { [key: number]: ProblemTag }): ProblemView {
  const result: ProblemView = {} as ProblemView;
  result.id = item.id;
  result.key = item.key;
  result.inserter = item.inserter;
  result.title = item.title;
  result.tags = [];
  if (item.tags) {
    for (const tag of item.tags) {
      const tagData = tagsMap[tag];
      if (tagData) {
        result.tags.push(tagData);
      }
    }
  }
  result.private = item.private;
  if (item.accept) {
    result.accept = item.accept;
  } else {
    result.accept = 0;
  }
  if (item.attempt) {
    result.attempt = item.attempt;
  } else {
    result.attempt = 0;
  }

  if (item.description != undefined) {
    result.description = item.description;
  }
  if (item.time_limit != undefined && item.time_limit >= 0) {
    result.timeLimit = item.time_limit.toString() + " ms";
  } else {
    result.timeLimit = "未知";
  }
  if (item.memory_limit != undefined && item.memory_limit >= 0) {
    result.memoryLimit = (item.memory_limit / 1024).toFixed(2) + " MB";
  } else {
    result.memoryLimit = "未知";
  }
  if (item.judge_type != undefined) {
    result.judgeType = GetJudgeTypeStr(item.judge_type);
  }
  if (item.space_type != undefined) {
    result.spaceType = GetSpaceTypeStr(item.space_type);
  }
  if (item.insert_time != undefined) {
    result.insertTime = new Date(item.insert_time).toLocaleString();
  }
  if (item.modify_time != undefined) {
    result.modifyTime = new Date(item.modify_time).toLocaleString();
  }
  if (item.modifier_nickname != undefined) {
    result.inserterNickname = item.modifier_nickname;
  }
  if (item.source != undefined) {
    // 判断item.source是否符合[]()格式，是否赋值result.sourceUrl
    const urlRegex = /\[([^\]]+)\]\(([^)]+)\)/;
    const match = item.source.match(urlRegex);
    if (match) {
      result.source = match[1];
      result.sourceUrl = match[2];
    } else {
      result.source = item.source;
      result.sourceUrl = "";
    }
  }
  if (item.judge_md5 != undefined) {
    result.judgeMd5 = item.judge_md5;
  }
  if (item.origin_oj != undefined) {
    result.originOj = item.origin_oj;
  }
  if (item.origin_id != undefined) {
    result.originId = item.origin_id;
  }
  if (item.origin_url != undefined) {
    result.originUrl = item.origin_url;
  }
  if (item.origin_author != undefined) {
    result.originAuthor = item.origin_author;
  }
  if (item.template != undefined) {
    result.template = item.template;
  }
  if (item.immutable_regions != undefined) {
    result.immutableRegions = item.immutable_regions;
  }

  return result;
}

export function ParseProblemDaily(item: ProblemDaily, tagsMap: { [key: number]: ProblemTag }): ProblemDailyView {
  const result: ProblemDailyView = {} as ProblemDailyView;
  result.key = item.key;
  result.problemId = item.problem_id;
  result.problemKey = item.problem_key;
  result.title = item.title;
  result.tags = [];
  if (item.tags) {
    for (const tag of item.tags) {
      const tagData = tagsMap[tag];
      if (tagData) {
        result.tags.push(tagData);
      }
    }
  }
  if (item.accept) {
    result.accept = item.accept;
  } else {
    result.accept = 0;
  }
  if (item.attempt) {
    result.attempt = item.attempt;
  } else {
    result.attempt = 0;
  }
  result.solution = item.solution;
  result.code = item.code;

  if (item.insert_time != undefined) {
    result.insertTime = new Date(item.insert_time).toLocaleString();
  }
  if (item.modify_time != undefined) {
    result.modifyTime = new Date(item.modify_time).toLocaleString();
  }
  if (item.inserter_nickname != undefined) {
    result.inserterNickname = item.inserter_nickname;
  }
  if (item.modifier_nickname != undefined) {
    result.modifierNickname = item.modifier_nickname;
  }

  return result;
}

export function ParseProblemRank(item: ProblemRank) {
  const result: ProblemRankView = {} as ProblemRankView;

  result.id = item.id;
  if (item.time) {
    result.time = formatTime(item.time);
  } else {
    result.time = "-";
  }
  if (item.memory) {
    result.memory = formatMemory(item.memory);
  } else {
    result.memory = "-";
  }

  result.language = item.language;
  result.codeLength = item.code_length;
  if (item.insert_time) {
    result.insertTime = new Date(item.insert_time).toLocaleString();
  } else {
    result.insertTime = "-";
  }
  result.inserter = item.inserter;
  result.inserterUsername = item.inserter_username;
  result.inserterNickname = item.inserter_nickname;
  result.inserterEmail = item.inserter_email;
  result.private = item.private;
  return result;
}

export function GetProblem(problemKey: string, contestId: number | undefined, problemIndex: number | undefined) {
  const params = {} as any;
  if (problemKey) {
    params.key = problemKey;
  } else {
    params.contest_id = contestId;
    params.problem_index = problemIndex;
  }
  return httpRequest({
    url: `/problem?${new URLSearchParams(params).toString()}`,
    method: "get",
  });
}

